-- =============================================
-- ICD-10 Diagnosis Codes Reference Table
-- Reference/lookup data for the `diagnoses` entity
-- Generated from: icd10 with code number.xlsx
-- Sheet: Valid ICD10 FY2026 & NF Exclude
-- Total rows: ~73,889
-- =============================================

-- This is a reference table that supports the `diagnoses` entity.
-- The `diagnoses.icd10_code` column references `icd10_codes.code`.

CREATE TABLE IF NOT EXISTS `icd10_codes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(10) NOT NULL COMMENT 'ICD-10 code, referenced by diagnoses.icd10_code',
  `short_description` varchar(500) NOT NULL,
  `long_description` varchar(1000) DEFAULT NULL,
  `is_nf_excluded` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `icd10_codes_code_unique` (`code`),
  KEY `icd10_codes_short_description_index` (`short_description`(255))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='ICD-10 diagnosis code reference table for the diagnoses entity';

SET @OLD_AUTOCOMMIT=@@AUTOCOMMIT, @@AUTOCOMMIT=0;
LOCK TABLES `icd10_codes` WRITE;
/*!40000 ALTER TABLE `icd10_codes` DISABLE KEYS */;











































































/*!40000 ALTER TABLE `icd10_codes` ENABLE KEYS */;
UNLOCK TABLES;
COMMIT;
SET AUTOCOMMIT=@OLD_AUTOCOMMIT;

-- Link diagnoses.icd10_code to this reference table
-- (Must run AFTER data insertion so FK validation finds matching codes)
ALTER TABLE `diagnoses`
  ADD CONSTRAINT `diagnoses_icd10_code_foreign`
  FOREIGN KEY (`icd10_code`) REFERENCES `icd10_codes` (`code`)
  ON DELETE RESTRICT
  ON UPDATE CASCADE;
